<script setup>
import {ref,computed} from 'vue';import {useRouter,useRoute,RouterLink} from 'vue-router';import {supabase} from '../services/supabase';
const route=useRoute(),router=useRouter(),name=ref(''),email=ref(''),password=ref(''),confirm=ref(''),type=ref(route.query.type==='employer'?'employer':'student'),company=ref(''),businessReg=ref(''),error=ref(''),done=ref(false),loading=ref(false);const passOk=computed(()=>password.value.length>=8&&/[A-Za-z]/.test(password.value)&&/\d/.test(password.value));async function register(){error.value='';if(!passOk.value){error.value='Use at least 8 characters with a letter and a number.';return}if(password.value!==confirm.value){error.value='Your passwords do not match.';return}if(type.value==='student'&&!/^[^\s@]+@[^\s@]+\.ac\.za$/i.test(email.value)){error.value='Please use your institution email address ending in .ac.za.';return}if(type.value==='employer'&&!company.value.trim()){error.value='Enter your business or organisation name.';return}loading.value=true;try{const {data,error:e}=await supabase.auth.signUp({email:email.value.trim(),password:password.value,options:{emailRedirectTo:`${location.origin}/login?verified=1`,data:{full_name:name.value.trim(),account_type:type.value,company_name:company.value.trim(),business_registration:businessReg.value.trim()}}});if(e)throw e;if(data.session)await supabase.auth.signOut();done.value=true}catch(e){error.value=e.message||'Could not create your account.'}finally{loading.value=false}}
</script>
<template><div class="auth-wrap"><section class="auth-brand"><span class="brand-mark">C</span><span class="eyebrow">MAKE YOUR NEXT MOVE</span><h1>Big goals start with one opportunity.</h1><p>Create your Campus Gig account and connect with work that moves you forward.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><span class="badge">Flexible work</span><span class="badge">Local opportunities</span><span class="badge">Real experience</span></div></section><section class="auth-panel"><form v-if="!done" class="auth-form" @submit.prevent="register"><RouterLink to="/" class="muted">← Back to Campus Gig</RouterLink><h2 style="margin-top:25px">Create your account</h2><p>Join as a student or an employer.</p><div v-if="error" class="alert error">{{error}}</div><div class="field"><label>I want to join as</label><select v-model="type" class="input"><option value="student">Student looking for work</option><option value="employer">Employer hiring students</option></select></div><div class="field"><label>Full name</label><input v-model="name" class="input" required placeholder="Your full name"></div><div v-if="type==='employer'" class="field"><label>Business / organisation</label><input v-model="company" class="input" required placeholder="Company or organisation name"></div><div class="field"><label>Email address</label><input v-model="email" class="input" type="email" required :placeholder="type==='student'?'name@mycput.ac.za':'you@company.co.za'"></div><small v-if="type==='student'" class="muted">Students must use a valid institution email ending in .ac.za.</small><div class="field" style="margin-top:14px"><label>Password</label><input v-model="password" class="input" type="password" required placeholder="At least 8 characters"></div><div class="field"><label>Confirm password</label><input v-model="confirm" class="input" type="password" required placeholder="Repeat password"></div><button class="btn btn-primary" style="width:100%" :disabled="loading">{{loading?'Creating account…':'Create account'}}</button><p style="text-align:center">Already have an account? <RouterLink to="/login" style="color:var(--green);font-weight:800">Sign in</RouterLink></p></form><div v-else class="auth-form"><span class="brand-mark">✓</span><h2 style="margin-top:24px">Check your inbox</h2><p>We’ve sent a verification link to <b>{{email}}</b>. Verify your email, then sign in to Campus Gig.</p><RouterLink to="/login" class="btn btn-primary">Go to sign in</RouterLink></div></section></div></template>
